// This code was generated by GPT-6, then heavily modified to fit the game better
import java.util.ArrayList;
import java.util.Scanner;

public class Battle {
    public static final int HAND_SIZE = 5;
    public static final int START_HEALTH = 1000;
    public static final int WIN_REWARD = 75;

    private final HumanPlayer human;
    private final CPUPlayer cpu;
    private final Scanner input;

    public Battle(HumanPlayer human, CPUPlayer cpu, Scanner input) {
        this.human = human;
        this.cpu = cpu;
        this.input = input;
    }

    public boolean fight() {
        human.drawCardsIntoHand();

        ArrayList<Person_Card> humanFighters = personCards(human.getHand());

        ArrayList<Person_Card> cpuFighters = personCards(cpu.getHand());

        if (humanFighters.isEmpty() || cpuFighters.isEmpty()) {
            System.out.println("A side has no Person cards. Battle cancelled.");
            return false;
        }

        int humanMult = teamMultiplier(human.getHand());
        int cpuMult = teamMultiplier(cpu.getHand());

        int humanFurnDef = furnitureDefense(human.getHand());
        int cpuFurnDef = furnitureDefense(cpu.getHand());

        System.out.println("\n=== BATTLE START: " + human.getName() + " vs " + cpu.getName() + " ===");

        printHand("Your hand", human.getHand());
        printHand("Enemy hand", cpu.getHand());

        System.out.println("Your furniture bonus: x" + humanMult + " attack, +" + humanFurnDef + " defense");
        System.out.println("Enemy furniture bonus: x" + cpuMult + " attack, +" + cpuFurnDef + " defense");

        // sets health to 1000 if multiplier is less than or equal to 0
        human.resetHealth(START_HEALTH);
        cpu.resetHealth(START_HEALTH);

        if (humanFurnDef > 0) {
            // gives a bit more health, since games quickly become one-and-dones with high rarity cards
            human.resetHealth(START_HEALTH * (humanFurnDef / 10));
        }
        
        if (cpuFurnDef > 0) {
            cpu.resetHealth(START_HEALTH * (cpuFurnDef / 10));
        }


        int round = 1;

        // main battle loop!
        while (!human.isDefeated() && !cpu.isDefeated()) {

            System.out.println("\n--- Round " + round + " ---");

            System.out.println("Your HP: " + human.getHealth() + " | " + cpu.getName() + " HP: " + cpu.getHealth());

            Person_Card mine = chooseCard(humanFighters);

            // CPU randomly chooses one of its available Person cards.
            Person_Card theirs = cpuFighters.get((int) (Math.random() * cpuFighters.size()));

            System.out.println(cpu.getName() + " plays: " + theirs.getName());

            // Calculate simultaneous damage.
            int toCpu = Math.max(1, mine.calculateDmg(humanMult) - (theirs.getDefense() + cpuFurnDef / 10));

            int toHuman = Math.max(1, theirs.calculateDmg(cpuMult) - (mine.getDefense() + humanFurnDef / 10));

            human.attack(cpu, toCpu);
            cpu.attack(human, toHuman);

            System.out.println(mine.getName() + " hits for " + toCpu + "!");

            System.out.println(theirs.getName() + " hits you for " + toHuman + "!");

            round++;
        }

        boolean won = cpu.isDefeated() && !human.isDefeated();

        human.addRecord(cpu);

        System.out.println("\n=== BATTLE OVER ===");

        if (won) {
            System.out.println("You win! +$" + WIN_REWARD);
        } else if (human.isDefeated() && cpu.isDefeated()) {
            System.out.println("Double knockout. It's a draw.");
        } else {
            System.out.println("You lost. Better luck next time!");
        }

        return won;
    }

    private Person_Card chooseCard(
            ArrayList<Person_Card> fighters) {

        while (true) {
            System.out.println("\nChoose a card to play:");

            for (int i = 0; i < fighters.size(); i++) {
                System.out.println((i + 1) + ") " + fighters.get(i));
            }

            System.out.print("> ");

            try {
                int pick = Integer.parseInt(input.nextLine().trim());

                if (pick >= 1 && pick <= fighters.size()) {
                    return fighters.get(pick - 1);
                }

            } catch (NumberFormatException ignored) {
            }

            System.out.println("Please enter a number from 1 to "
                    + fighters.size() + ".");
        }
    }

    private static ArrayList<Person_Card> personCards(ArrayList<Cards> hand) {

        ArrayList<Person_Card> result = new ArrayList<>();

        for (Cards c : hand) {
            if (c instanceof Person_Card) {
                result.add((Person_Card) c);
            }
        }

        return result;
    }

    private static int teamMultiplier(ArrayList<Cards> hand) {

        int mult = 1;

        for (Cards c : hand) {
            if (c instanceof Furniture_Card) {
                mult += ((Furniture_Card) c).getMultiplier();
            }
        }

        return mult;
    }

    private static int furnitureDefense(ArrayList<Cards> hand) {

        int def = 0;

        for (Cards c : hand) {
            if (c instanceof Furniture_Card) {
                def += c.getDefense();
            }
        }

        return def;
    }

    private static void printHand(
            String label, ArrayList<Cards> hand) {

        System.out.println(label + ":");

        for (Cards c : hand) {
            System.out.println("  " + c);
        }
    }
}
